const { Worker, isMainThread, parentPort } = require('worker_threads');

// Demonstrates Atomics.add (wait-free counter) vs naive increment (data race)

const ITERATIONS = 100_000;

if (isMainThread) {
  // Shared memory: 2 Int32 slots — [0] for atomic counter, [1] for racy counter
  const sab = new SharedArrayBuffer(8);
  const shared = new Int32Array(sab);

  // Spawn 4 worker threads all incrementing simultaneously
  const workers = Array.from({ length: 4 }, () =>
    new Promise((resolve, reject) => {
      const w = new Worker(__filename, {
        workerData: null,
        // Pass SAB via workerData is not needed; use transferList trick:
      });
      // Simpler: workers receive SAB through postMessage
      w.once('online', () => w.postMessage(sab));
      w.on('message', resolve);
      w.on('error', reject);
    })
  );

  Promise.all(workers).then(() => {
    const expected = 4 * ITERATIONS;
    console.log(`Expected:       ${expected}`);
    console.log(`Atomic counter: ${shared[0]}  (should equal expected)`);
    console.log(`Racy counter:   ${shared[1]}  (likely LESS due to lost updates)`);
    // Atomic: always correct — Atomics.add is indivisible
    // Racy:   lost updates — read-modify-write not atomic, threads overwrite each other
  });
} else {
  parentPort.once('message', (sab) => {
    const shared = new Int32Array(sab);
    for (let i = 0; i < ITERATIONS; i++) {
      // CORRECT: atomic fetch-and-add (wait-free)
      Atomics.add(shared, 0, 1);

      // RACY (illustrative — do not do this):
      // const val = shared[1];  // read
      // shared[1] = val + 1;    // write — another thread may overwrite!
    }
    parentPort.postMessage('done');
  });
}

// Compare-And-Swap (CAS) loop — the building block of lock-free structures
// Simulated with Atomics.compareExchange (actual CAS instruction)

const sab = new SharedArrayBuffer(4);
const view = new Int32Array(sab);
view[0] = 0; // initial value

function atomicIncrement(arr, index, amount) {
  // CAS loop: read → compute → swap atomically, retry on failure
  while (true) {
    const expected = Atomics.load(arr, index);  // read current value
    const desired = expected + amount;           // compute new value
    // CAS: only writes if arr[index] === expected
    const actual = Atomics.compareExchange(arr, index, expected, desired);
    if (actual === expected) {
      return desired; // CAS succeeded — we are done
    }
    // CAS failed — another thread changed the value; retry with fresh read
  }
}

// Version-stamped value to prevent ABA problem
const vab = new SharedArrayBuffer(8); // [value, version]
const vstamp = new Int32Array(vab);

function casWithVersion(arr, expectedVal, expectedVer, newVal) {
  // Atomically check BOTH value and version before updating
  // In real systems, use a 128-bit CAS or tagged pointer
  const curVal = Atomics.load(arr, 0);
  const curVer = Atomics.load(arr, 1);
  if (curVal === expectedVal && curVer === expectedVer) {
    Atomics.store(arr, 0, newVal);
    Atomics.add(arr, 1, 1); // increment version
    return true;
  }
  return false; // ABA detected — version mismatch
}
